mapper.update:
update clazz
name=#{name}, room=#{room}, begin_date=#{beginDate}, end_date=#{endDate}, master_id=#{masterId}, subject=#{subject}
where id=#{id}

mapper.select:
select c.id, c.name, c.room, c.begin_date as beginDate, c.end_date as endDate, c.master_id as masterId, c.subject, c.create_time as createTime, c.update_time as updateTime, e.name as masterName, (case when CURRENT_DATE()>c.end_date then '已结课' when CURRENT_DATE()<=c.begin_date then '未结课' else '在读中' end) as status from clazz c left join emp e on c.master_id=e.id
c.name like concat('%',#{name},'%')
and c.end_date >=#{begin}
and c.begin_date <= #{end}
order by c.update_time desc
